<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Throwable; use Pterodactyl\Models\Server; use Aternos\Nbt\Tag\CompoundTag; use Illuminate\Http\JsonResponse; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Storage; use Symfony\Component\HttpFoundation\Response; use Pterodactyl\Jobs\Dezerx\RenderPlayerMapTile; use Pterodactyl\Services\Dezerx\Minecraft\Nbt; use Pterodactyl\Services\Dezerx\Minecraft\MapRenderer; use Pterodactyl\Services\Dezerx\Minecraft\PlayerData; use Pterodactyl\Services\Dezerx\Minecraft\PlayerFiles; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Services\Dezerx\Minecraft\PlayerRoster; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Players\PlayerRequest; class PlayerMapController extends ClientApiController { private const REGION = 512; private const TILES = 'dezerx/player-map'; private const LISTING_TTL = 60; private const REDRAW_AFTER = 600; private const PENDING_TTL = 300; private const KEEP_FOR = 14 * 86400; private const NEARBY_LIMIT = 40; private const NEARBY_TTL = 60; private const DIMENSION = ['required', 'string', 'max:128', 'regex:/^[a-z0-9_.-]+:[a-z0-9_.\/-]+$/', 'not_regex:/\.\./']; private const VIEW = [ 'dimension' => self::DIMENSION, 'x' => ['required', 'numeric', 'between:-30000000,30000000'], 'z' => ['required', 'numeric', 'between:-30000000,30000000'], 'span' => ['required', 'integer', 'in:128,256,512'], ]; public function index(PlayerRequest $request, Server $server): JsonResponse { $data = $request->validate(self::VIEW); $files = new ServerFiles($server); $folder = $this->folder($files, $server->uuid, $data['dimension']); $sky = $this->sky($files, $server->uuid); $this->prune(); if ($folder['path'] === null) { return new JsonResponse(['available' => false, 'regions' => [], 'sky' => $sky]); } [$x, $z, $left, $top, $span] = $this->window($data); $home = [$this->cell($x), $this->cell($z)]; $regions = [$home]; for ($rz = $this->cell($top); $rz <= $this->cell($top + $span - 1); $rz++) { for ($rx = $this->cell($left); $rx <= $this->cell($left + $span - 1); $rx++) { if ([$rx, $rz] !== $home) { $regions[] = [$rx, $rz]; } } } return new JsonResponse([ 'available' => true, 'regions' => array_map(fn (array $region) => $this->region($server, $folder, ...$region), $regions), 'sky' => $sky, ]); } public function tile(PlayerRequest $request, Server $server): Response { $data = $request->validate([ 'dimension' => self::DIMENSION, 'x' => ['required', 'integer', 'between:-60000,60000'], 'z' => ['required', 'integer', 'between:-60000,60000'], 'v' => ['required', 'integer', 'min:0'], ]); $folder = $this->folder(new ServerFiles($server), $server->uuid, $data['dimension']); $name = "r.{$data['x']}.{$data['z']}.mca"; if ($folder['path'] === null || !isset($folder['regions'][$name])) { abort(404); } $tile = $this->base($server->uuid, "{$folder['path']}/{$name}") . "-{$data['v']}.png"; $png = is_file($tile) ? @file_get_contents($tile) : false; if ($png === false || $png === '') { abort(404); } @touch($tile); return new Response($png, 200, [ 'Content-Type' => 'image/png', 'Cache-Control' => 'private, max-age=86400, immutable', 'X-Content-Type-Options' => 'nosniff', 'Content-Security-Policy' => "default-src 'none'; sandbox", ]); } public function nearby(PlayerRequest $request, Server $server): JsonResponse { $data = $request->validate(self::VIEW); [, , $left, $top, $span] = $this->window($data); $files = new ServerFiles($server); $online = []; foreach (Cache::get("dezerx:players:{$server->uuid}") ?? [] as $row) { if (($row['online'] ?? false) === true) { $online[strtolower((string) $row['uuid'])] = true; } } $players = array_values(array_filter( Cache::remember( "dezerx:playermap:positions:{$server->uuid}", self::NEARBY_TTL, fn () => $this->positions($files, $server->uuid), ), fn (array $player) => $player['dimension'] === $data['dimension'] && $player['x'] >= $left && $player['x'] < $left + $span && $player['z'] >= $top && $player['z'] < $top + $span, )); return new JsonResponse([ 'players' => array_map(fn (array $player) => [ 'uuid' => $player['uuid'], 'name' => $player['name'], 'x' => $player['x'], 'z' => $player['z'], 'online' => isset($online[strtolower($player['uuid'])]), ], $players), ]); } private function region(Server $server, array $folder, int $x, int $z): array { $name = "r.{$x}.{$z}.mca"; if (!isset($folder['regions'][$name])) { return ['x' => $x, 'z' => $z, 'state' => 'missing']; } $file = "{$folder['path']}/{$name}"; $base = $this->base($server->uuid, $file); $modified = $folder['regions'][$name]; $versions = []; foreach (glob("{$base}-*.png") ?: [] as $tile) { if (preg_match('/-(\d+)\.png$/', $tile, $match) === 1) { $versions[(int) $match[1]] = $tile; } } krsort($versions); $latest = array_key_first($versions); foreach (array_slice($versions, 1, null, true) as $tile) { @unlink($tile); } if ($latest === null) { $this->queue($server, $file, "{$base}-{$modified}.png"); return ['x' => $x, 'z' => $z, 'state' => 'rendering']; } $refreshing = false; if ($modified > $latest) { $next = "{$base}-{$modified}.png"; if (Cache::add('dezerx:playermap:redraw:' . sha1($base), true, self::REDRAW_AFTER)) { $this->queue($server, $file, $next); } $refreshing = Cache::has(RenderPlayerMapTile::pendingKey($next)); } return ['x' => $x, 'z' => $z, 'state' => 'ready', 'version' => $latest, 'refreshing' => $refreshing]; } private function queue(Server $server, string $file, string $destination): void { if (Cache::add(RenderPlayerMapTile::pendingKey($destination), true, self::PENDING_TTL)) { RenderPlayerMapTile::dispatch($server, $file, $destination); } } private function folder(ServerFiles $files, string $server, string $dimension): array { return Cache::remember( "dezerx:playermap:folder:{$server}:" . sha1($dimension), self::LISTING_TTL, function () use ($files, $server, $dimension) { $level = PlayerFiles::dirs($files, $server)['level']; $best = ['path' => null, 'regions' => [], 'written' => 0]; foreach ($this->candidates($level, $dimension) as $path) { $regions = []; foreach ($files->listFiles($path) ?? [] as $entry) { $name = (string) ($entry['name'] ?? ''); if (preg_match('/^r\.-?\d+\.-?\d+\.mca$/', $name) === 1 && (int) ($entry['size'] ?? 0) > 0) { $regions[$name] = (int) strtotime((string) ($entry['modified_at'] ?? '')) ?: 0; } } $written = $regions === [] ? 0 : max($regions); if ($regions !== [] && ($best['path'] === null || $written > $best['written'])) { $best = ['path' => $path, 'regions' => $regions, 'written' => $written]; } } return $best; }, ); } private function candidates(string $level, string $dimension): array { [$space, $name] = explode(':', $dimension, 2); $modern = "/{$level}/dimensions/{$space}/{$name}/region"; return match ($dimension) { 'minecraft:overworld' => ["/{$level}/region", $modern], 'minecraft:the_nether' => ["/{$level}/DIM-1/region", "/{$level}_nether/DIM-1/region", $modern], 'minecraft:the_end' => ["/{$level}/DIM1/region", "/{$level}_the_end/DIM1/region", $modern], default => [$modern], }; } private function sky(ServerFiles $files, string $server): ?array { $saved = Cache::remember("dezerx:playermap:sky:{$server}", self::LISTING_TTL, function () use ($files, $server) { $level = PlayerFiles::dirs($files, $server)['level']; $raw = $files->fileContents("/{$level}/level.dat", 4_000_000); if ($raw === null) { return false; } try { [$plain] = Nbt::decompress($raw); $data = Nbt::parse($plain)->get('Data'); } catch (Throwable) { return false; } if (!$data instanceof CompoundTag) { return false; } $value = fn (?CompoundTag $tag, string $key) => $tag?->get($key)?->getValue(); $rules = $data->get('GameRules'); $modern = $data->get('game_rules'); $cycle = $rules instanceof CompoundTag ? $value($rules, 'doDaylightCycle') !== 'false' : !($modern instanceof CompoundTag && (int) $value($modern, 'minecraft:advance_time') === 0); $saved = null; foreach ($files->listFiles("/{$level}") ?? [] as $entry) { if (($entry['name'] ?? null) === 'level.dat') { $saved = strtotime((string) ($entry['modified_at'] ?? '')) ?: null; } } return [ 'time' => (int) $value($data, 'DayTime'), 'raining' => (int) $value($data, 'raining') === 1, 'thundering' => (int) $value($data, 'thundering') === 1, 'cycle' => $cycle, 'saved' => $saved, 'running' => $files->powerStateOrNull() === 'running', ]; }); if ($saved === false) { return null; } $time = $saved['time']; if ($saved['running'] && $saved['cycle'] && $saved['saved'] !== null) { $time += max(0, time() - $saved['saved']) * 20; } return [ 'time' => (($time % 24000) + 24000) % 24000, 'raining' => $saved['raining'], 'thundering' => $saved['thundering'], ]; } private function positions(ServerFiles $files, string $server): array { $directory = PlayerFiles::dirs($files, $server)['data']; $entries = array_filter( $files->listFiles($directory) ?? [], fn (array $entry) => preg_match('/^[0-9a-f-]{36}\.dat$/i', (string) ($entry['name'] ?? '')) === 1, ); usort($entries, fn (array $a, array $b) => strcmp((string) ($b['modified_at'] ?? ''), (string) ($a['modified_at'] ?? ''))); $names = PlayerRoster::names($files, $server); $out = []; foreach (array_slice($entries, 0, self::NEARBY_LIMIT) as $entry) { $uuid = substr($entry['name'], 0, -4); $raw = $files->fileContents("{$directory}/{$entry['name']}", ServerFiles::MAX_PLAYER_FILE); if ($raw === null) { continue; } try { [$plain] = Nbt::decompress($raw); $summary = PlayerData::summarize(Nbt::parse($plain)); } catch (Throwable) { continue; } if (($summary['position'] ?? null) === null) { continue; } $out[] = [ 'uuid' => $uuid, 'name' => $names[strtolower($uuid)] ?? null, 'dimension' => (string) ($summary['dimension'] ?? 'minecraft:overworld'), 'x' => (float) $summary['position']['x'], 'z' => (float) $summary['position']['z'], ]; } return $out; } private function prune(): void { if (!Cache::add('dezerx:playermap:pruned', true, 86400)) { return; } $cutoff = time() - self::KEEP_FOR; foreach (glob($this->directory() . '/*.png') ?: [] as $tile) { if (@filemtime($tile) < $cutoff) { @unlink($tile); } } } private function window(array $data): array { $x = (int) floor((float) $data['x']); $z = (int) floor((float) $data['z']); $span = (int) $data['span']; return [$x, $z, $x - intdiv($span, 2), $z - intdiv($span, 2), $span]; } private function base(string $server, string $file): string { return $this->directory() . "/{$server}-" . sha1($file . '|' . MapRenderer::REVISION); } private function directory(): string { $disk = Storage::disk('local'); if (!$disk->directoryExists(self::TILES)) { $disk->makeDirectory(self::TILES); } return $disk->path(self::TILES); } private function cell(int $block): int { return (int) floor($block / self::REGION); } } 